@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  /* Colors */
  --bg-deep: #0D1B2A;
  --bg-surface: #1B2838;
  --bg-surface-hover: #263547;
  --brand-primary: #15295A;
  --brand-accent-teal: #00B4D8;
  --brand-accent-blue: #0077B6;
  --brand-accent-green: #6CC24A;

  --text-main: #FFFFFF;
  --text-muted: #A0AEC0;
  --border-color: #3C424B;

  /* Typography */
  --font-family: 'Inter', sans-serif;

  /* Spacing */
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 4rem;
  --spacing-xl: 6rem;

  /* Layout */
  --container-width: 1200px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-deep);
  color: var(--text-main);
  line-height: 1.6;
  font-size: 16px;
  overflow-x: hidden;
}

a {
  color: var(--text-main);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--brand-accent-teal);
}

ul {
  list-style: none;
}

/* Layout Utilities */
.container {
  max-width: var(--container-width);
  margin: 0 auto;
  padding: 0 var(--spacing-sm);
}

.section {
  padding: var(--spacing-xl) 0;
}

.section-light {
  background-color: var(--bg-surface);
}

.text-center { text-align: center; }
.mb-sm { margin-bottom: var(--spacing-sm); }
.mb-md { margin-bottom: var(--spacing-md); }
.mb-lg { margin-bottom: var(--spacing-lg); }

/* Typography */
h1, h2, h3, h4 {
  line-height: 1.2;
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
}

h1 { font-size: 3.5rem; letter-spacing: -0.02em; }
h2 { font-size: 2.5rem; }
h3 { font-size: 1.75rem; }
p { color: var(--text-muted); margin-bottom: var(--spacing-sm); }
p.lead { font-size: 1.25rem; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: 4px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  font-size: 1rem;
}

.btn-primary {
  background-color: var(--brand-accent-teal);
  color: var(--bg-deep);
}

.btn-primary:hover {
  background-color: var(--brand-accent-blue);
  color: var(--text-main);
}

.btn-outline {
  background-color: transparent;
  border: 1px solid var(--brand-accent-teal);
  color: var(--brand-accent-teal);
}

.btn-outline:hover {
  background-color: var(--brand-accent-teal);
  color: var(--bg-deep);
}

/* Header & Nav */
header {
  background-color: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(10px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid var(--border-color);
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo span {
  color: var(--brand-accent-teal);
}

.nav-links {
  display: flex;
  gap: 2rem;
  align-items: center;
}

/* Dropdown */
.dropdown {
  position: relative;
}

.dropdown-toggle {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  cursor: pointer;
}

.dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all 0.2s ease;
  box-shadow: 0 10px 25px rgba(0,0,0,0.5);
}

.dropdown:hover .dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.dropdown-menu li a {
  display: block;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
}

.dropdown-menu li:last-child a {
  border-bottom: none;
}

.dropdown-menu li a:hover {
  background-color: var(--bg-surface-hover);
  color: var(--brand-accent-teal);
}

/* Hero Section */
.hero {
  padding: 8rem 0;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(0, 180, 216, 0.15) 0%, rgba(13, 27, 42, 0) 70%);
  z-index: -1;
}

.hero-content {
  max-width: 800px;
}

.hero-actions {
  display: flex;
  gap: 1rem;
  margin-top: 2rem;
}

/* Featured Product Banner */
.featured-banner {
  background: linear-gradient(90deg, var(--brand-primary), var(--bg-surface));
  padding: 2rem 0;
  border-top: 1px solid var(--brand-accent-teal);
  border-bottom: 1px solid var(--brand-accent-teal);
}

.banner-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.banner-text h3 {
  margin-bottom: 0;
  color: var(--brand-accent-teal);
}

.banner-text p {
  margin-bottom: 0;
  color: var(--text-main);
}

/* Grid Layouts */
.grid {
  display: grid;
  gap: 2rem;
}

.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

/* Cards */
.card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  padding: 2rem;
  border-radius: 8px;
  transition: transform 0.3s ease, border-color 0.3s ease;
}

.card:hover {
  transform: translateY(-5px);
  border-color: var(--brand-accent-teal);
}

.card-icon {
  width: 48px;
  height: 48px;
  background-color: rgba(0, 180, 216, 0.1);
  color: var(--brand-accent-teal);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
}

.card h3 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

/* Tabs Component */
.tabs-container {
  margin-top: 3rem;
}

.tabs-nav {
  display: flex;
  gap: 1rem;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 2rem;
  overflow-x: auto;
  white-space: nowrap;
  padding-bottom: 1px;
}

.tab-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  padding: 1rem 1.5rem;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all 0.2s ease;
}

.tab-btn:hover {
  color: var(--text-main);
}

.tab-btn.active {
  color: var(--brand-accent-teal);
  border-bottom-color: var(--brand-accent-teal);
}

.tab-pane {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-pane.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Accordion Component */
.accordion {
  border-top: 1px solid var(--border-color);
}

.accordion-item {
  border-bottom: 1px solid var(--border-color);
}

.accordion-header {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1.5rem 0;
  color: var(--text-main);
  font-size: 1.25rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.accordion-header::after {
  content: "+";
  font-size: 1.5rem;
  color: var(--brand-accent-teal);
  transition: transform 0.3s ease;
}

.accordion-item.active .accordion-header::after {
  content: "−";
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.accordion-item.active .accordion-content {
  max-height: 500px; /* arbitrary max height for animation */
}

.accordion-body {
  padding-bottom: 1.5rem;
  color: var(--text-muted);
}

/* Diagrams / Visuals */
.diagram-container {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 3rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
  position: relative;
}

/* Ecosystem Diagram */
.ecosystem-diagram {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 2rem;
  width: 100%;
}
.pillar {
  flex: 1;
  background-color: var(--bg-deep);
  border: 1px solid var(--brand-accent-blue);
  border-radius: 8px;
  padding: 2rem;
  text-align: center;
  position: relative;
}
.pillar-title {
  color: var(--brand-accent-teal);
  font-weight: 600;
  margin-bottom: 1rem;
}
.diagram-link {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--brand-accent-teal);
  font-size: 2rem;
}

/* Stats (Circular) */
.stats-container {
  display: flex;
  justify-content: center;
  gap: 4rem;
  flex-wrap: wrap;
}

.stat-circle {
  width: 200px;
  height: 200px;
  border-radius: 50%;
  border: 4px solid var(--border-color);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  position: relative;
  padding: 1rem;
}

.stat-circle::before {
  content: '';
  position: absolute;
  top: -4px; left: -4px; right: -4px; bottom: -4px;
  border-radius: 50%;
  border: 4px solid transparent;
  border-top-color: var(--brand-accent-teal);
  border-right-color: var(--brand-accent-teal);
  transform: rotate(-45deg);
}

.stat-value {
  font-size: 3rem;
  font-weight: 700;
  color: var(--text-main);
  line-height: 1;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* Timeline */
.timeline {
  position: relative;
  padding: 2rem 0;
}

.timeline::before {
  content: '';
  position: absolute;
  top: 0; bottom: 0;
  left: 20%;
  width: 2px;
  background-color: var(--border-color);
}

.timeline-item {
  display: flex;
  margin-bottom: 3rem;
  position: relative;
}

.timeline-time {
  width: 20%;
  padding-right: 2rem;
  text-align: right;
  font-weight: 700;
  color: var(--brand-accent-teal);
  font-size: 1.25rem;
}

.timeline-content {
  width: 80%;
  padding-left: 3rem;
  position: relative;
}

.timeline-content::before {
  content: '';
  position: absolute;
  left: -9px;
  top: 5px;
  width: 20px;
  height: 20px;
  background-color: var(--bg-surface);
  border: 3px solid var(--brand-accent-teal);
  border-radius: 50%;
}

.progress-bar-container {
  height: 8px;
  background-color: var(--bg-surface);
  border-radius: 4px;
  margin-top: 1rem;
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  background-color: var(--brand-accent-teal);
}

/* Testimonials Carousel */
.carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.carousel-inner {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  min-width: 100%;
  text-align: center;
  padding: 2rem;
}

.testimonial-text {
  font-size: 1.25rem;
  font-style: italic;
  margin-bottom: 1.5rem;
  color: var(--text-main);
}

.testimonial-author {
  color: var(--brand-accent-teal);
  font-weight: 600;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}

.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: var(--border-color);
  cursor: pointer;
  border: none;
}

.dot.active {
  background-color: var(--brand-accent-teal);
}

/* Forms */
.form-group {
  margin-bottom: 1.5rem;
}

.form-label {
  display: block;
  margin-bottom: 0.5rem;
  color: var(--text-main);
  font-weight: 500;
}

.form-control {
  width: 100%;
  padding: 0.75rem 1rem;
  background-color: var(--bg-deep);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-main);
  font-family: var(--font-family);
  transition: border-color 0.2s ease;
}

.form-control:focus {
  outline: none;
  border-color: var(--brand-accent-teal);
}

.form-error {
  color: #EF4444;
  font-size: 0.875rem;
  margin-top: 0.5rem;
  display: none;
}

.form-group.error .form-control {
  border-color: #EF4444;
}

.form-group.error .form-error {
  display: block;
}

/* List with checks */
.check-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.check-list li {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
}
.check-list li::before {
  content: '✓';
  color: var(--brand-accent-teal);
  font-weight: bold;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background-color: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  padding: 1rem;
  display: flex;
  justify-content: center;
  z-index: 2000;
  transform: translateY(100%);
  transition: transform 0.3s ease;
}

.cookie-banner.show {
  transform: translateY(0);
}

.cookie-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: var(--container-width);
  gap: 2rem;
}

.cookie-actions {
  display: flex;
  gap: 1rem;
}

/* Footer */
footer {
  background-color: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer-col h4 {
  color: var(--text-main);
  font-size: 1.1rem;
  margin-bottom: 1.5rem;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-col a {
  color: var(--text-muted);
}

.footer-col a:hover {
  color: var(--brand-accent-teal);
}

.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 992px) {
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .ecosystem-diagram { flex-direction: column; }
  .diagram-link { transform: rotate(90deg); }
}

@media (max-width: 768px) {
  h1 { font-size: 2.5rem; }
  h2 { font-size: 2rem; }
  .grid-2 { grid-template-columns: 1fr; }
  .grid-3 { grid-template-columns: 1fr; }
  .grid-6 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .nav-links { display: none; /* In a full build, this would be a hamburger menu */ }
  .hero { padding: 4rem 0; }
  .banner-content { flex-direction: column; text-align: center; gap: 1rem; }
  .timeline::before { left: 0; }
  .timeline-item { flex-direction: column; }
  .timeline-time { width: 100%; text-align: left; padding-right: 0; margin-bottom: 0.5rem; padding-left: 2rem; }
  .timeline-content { width: 100%; padding-left: 2rem; }
  .cookie-content { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .grid-6 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
}

document.addEventListener('DOMContentLoaded', () => {

  // 1. Tabs Logic
  const initTabs = () => {
    const tabGroups = document.querySelectorAll('.tabs-container');

    tabGroups.forEach(group => {
      const tabBtns = group.querySelectorAll('.tab-btn');
      const tabPanes = group.querySelectorAll('.tab-pane');

      tabBtns.forEach(btn => {
        btn.addEventListener('click', () => {
          // Remove active classes
          tabBtns.forEach(b => b.classList.remove('active'));
          tabPanes.forEach(p => p.classList.remove('active'));

          // Add active class to current
          btn.classList.add('active');
          const targetId = btn.getAttribute('data-target');
          const targetPane = document.getElementById(targetId);
          if(targetPane) {
            targetPane.classList.add('active');
          }
        });
      });
    });
  };

  // 2. Accordion Logic
  const initAccordion = () => {
    const accordions = document.querySelectorAll('.accordion');

    accordions.forEach(acc => {
      const items = acc.querySelectorAll('.accordion-item');

      items.forEach(item => {
        const header = item.querySelector('.accordion-header');
        header.addEventListener('click', () => {
          const isActive = item.classList.contains('active');

          // Close all items in this accordion
          items.forEach(i => i.classList.remove('active'));

          // If it wasn't active, open it
          if (!isActive) {
            item.classList.add('active');
          }
        });
      });
    });
  };

  // 3. Testimonial Carousel Logic
  const initCarousel = () => {
    const carousels = document.querySelectorAll('.carousel');

    carousels.forEach(carousel => {
      const inner = carousel.querySelector('.carousel-inner');
      const cards = carousel.querySelectorAll('.testimonial-card');
      const dots = carousel.querySelectorAll('.dot');

      dots.forEach((dot, index) => {
        dot.addEventListener('click', () => {
          // Remove active class from all dots
          dots.forEach(d => d.classList.remove('active'));

          // Add active class to clicked dot
          dot.classList.add('active');

          // Translate inner container
          inner.style.transform = `translateX(-${index * 100}%)`;
        });
      });
    });
  };

  // 4. Form Validation Logic
  const initForm = () => {
    const demoForm = document.getElementById('demo-form');
    if (!demoForm) return;

    demoForm.addEventListener('submit', (e) => {
      e.preventDefault();
      let isValid = true;

      const requiredFields = demoForm.querySelectorAll('[required]');

      requiredFields.forEach(field => {
        const formGroup = field.closest('.form-group');
        const errorEl = formGroup.querySelector('.form-error');

        if (!field.value.trim()) {
          isValid = false;
          formGroup.classList.add('error');
          if(errorEl) errorEl.textContent = 'This field is required';
        } else {
          formGroup.classList.remove('error');
        }

        // Simple email validation if type is email
        if (field.type === 'email' && field.value.trim()) {
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailRegex.test(field.value)) {
            isValid = false;
            formGroup.classList.add('error');
            if(errorEl) errorEl.textContent = 'Please enter a valid email';
          }
        }
      });

      if (isValid) {
        // Show success state (normally would submit via fetch/AJAX)
        demoForm.innerHTML = '<div class="text-center p-4"><h3>Thank You!</h3><p>Your demo request has been submitted successfully. Our team will contact you shortly.</p></div>';
      }
    });

    // Clear errors on input
    const inputs = demoForm.querySelectorAll('.form-control');
    inputs.forEach(input => {
      input.addEventListener('input', () => {
        const group = input.closest('.form-group');
        if(group.classList.contains('error')) {
          group.classList.remove('error');
        }
      });
    });
  };

  // 5. Cookie Banner Logic
  const initCookieBanner = () => {
    const banner = document.getElementById('cookie-banner');
    if (!banner) return;

    // Check if already accepted/declined
    const cookiePref = localStorage.getItem('wellstream_cookie_pref');

    if (!cookiePref) {
      setTimeout(() => {
        banner.classList.add('show');
      }, 1000);
    }

    const acceptBtn = document.getElementById('cookie-accept');
    const declineBtn = document.getElementById('cookie-decline');

    if (acceptBtn) {
      acceptBtn.addEventListener('click', () => {
        localStorage.setItem('wellstream_cookie_pref', 'accepted');
        banner.classList.remove('show');
      });
    }

    if (declineBtn) {
      declineBtn.addEventListener('click', () => {
        localStorage.setItem('wellstream_cookie_pref', 'declined');
        banner.classList.remove('show');
      });
    }
  };

  // Initialize all components
  initTabs();
  initAccordion();
  initCarousel();
  initForm();
  initCookieBanner();
});
